from manim import *
import math
from math import pi


def _smart_text(text, font_size):
    """含非 ASCII 字符（中文/希腊字母/全角符号）用 Text（Pango 渲染，支持中文）；纯 ASCII 用 MathTex（LaTeX 渲染，支持数学公式）。"""
    return Text(text, font_size=font_size) if any(ord(c) > 127 for c in text) else MathTex(text, font_size=font_size)


class PolarPlotScene(Scene):
    def construct(self):
        expr = {{expr}}
        title_text = {{title}}

        plane = PolarPlane(radius_max=3, size=6)
        self.play(Create(plane))

        points = []
        steps = 400
        for i in range(steps + 1):
            t = 2 * PI * i / steps
            r = eval(expr, {"__builtins__": {}}, {"t": t, "np": np, "math": math})
            if r < 0:
                r = 0
            points.append([r * np.cos(t), r * np.sin(t), 0])
        curve = VMobject().set_points_smoothly(points).set_color(YELLOW).set_stroke(width=3)
        self.play(Create(curve), run_time=3)

        if title_text:
            title = _smart_text(title_text, font_size=52).to_edge(UP)
            self.play(Write(title))

        self.wait(2)
